import type { ReactNode } from "react"
import { useIsMobile } from "@/shared/lib/use-mobile"
import { DetailSurface } from "@/shared/ui/kit/detail-surface"
import { Page, type Crumb } from "@/shared/ui/kit/layout/page"
import { SettingsBody } from "./SettingsPage"

/** 상세가 놓이는 곳: 자기 페이지, 또는 목록 위 대화상자(닫기 · 페이지로 열기와 함께). */
export type AdminSurfaceOptions = { surface?: "page" | "dialog"; onClose?: () => void; onExpand?: () => void }

/**
 * 관리 화면의 상세 · 양식 하나: 제목 · 설명 아래 설정 단, 끝에 동작(footer: 저장 · 취소).
 * - 데스크톱 자기 페이지: 다른 상세와 같은 뒤로가기 틀(DetailSurface page). 둥근 ← 는 경로의 위 단계(목록)로 가고,
 *   동작은 단의 끝에 선다.
 * - 목록 위: 키트 대화상자에 같은 단, 동작은 끝에.
 * - 휴대폰: 늘 페이지(앱 바 ← 와 아래 동작 줄).
 */
export function AdminSurface({ surface = "page", onClose, onExpand, crumbs, title, description, actions, footer, children }: AdminSurfaceOptions & {
  crumbs: Crumb[]; title: string; description?: ReactNode; actions?: ReactNode; footer?: ReactNode; children: ReactNode
}) {
  const isMobile = useIsMobile()
  if (isMobile) return (
    <Page crumbs={crumbs} actions={actions} footer={footer} isFullScreen>
      <SettingsBody title={title} description={description}>{children}</SettingsBody>
    </Page>
  )
  if (surface === "page") return (
    <DetailSurface surface="page" title={title} crumbs={crumbs} actions={actions}>
      <SettingsBody title={title} description={description}>
        {children}
        {footer ? <div className="flex flex-wrap justify-end gap-2">{footer}</div> : null}
      </SettingsBody>
    </DetailSurface>
  )
  return (
    <DetailSurface surface="dialog" title={title} crumbs={crumbs} actions={actions} onClose={onClose} onExpand={onExpand}>
      <div className="flex min-w-0 flex-col gap-8">
        {description ? <p className="text-muted-foreground">{description}</p> : null}
        {children}
        {footer ? <div className="flex flex-wrap justify-end gap-2">{footer}</div> : null}
      </div>
    </DetailSurface>
  )
}

import type { ReactNode } from "react"
import { Page, useOwnPageTitle, type Crumb } from "@/shared/ui/kit/layout/page"

type SettingsBodyProps = {
  title: string
  /** 이 페이지가 정하는 것을 한 줄로. */
  description?: ReactNode
  children: ReactNode
}

/**
 * 설정 페이지의 안쪽: 가운데 한 열(최대 720px), 맨 위에 제목과 한 줄 설명,
 * 그 아래에 SettingsSection이 이어진다. 페이지 틀(Page)을 따로 그리는 곳(프로젝트 설정)은 이것만 쓴다.
 */
export function SettingsBody({ title, description, children }: SettingsBodyProps) {
  // 제목이 페이지의 h1이다(Page 머리 줄은 h1을 두지 않는다).
  useOwnPageTitle()
  return (
    // 앱 셸이 이미 main을 그리므로 여기서는 main을 겹치지 않는다.
    <div className="flex justify-center px-4 py-10 max-md:py-6">
      <div className="flex w-full max-w-180 min-w-0 flex-col gap-8">
        <header className="flex flex-col gap-1">
          <h1 className="text-2xl font-semibold tracking-tight">{title}</h1>
          {description && <p className="text-muted-foreground">{description}</p>}
        </header>
        {children}
      </div>
    </div>
  )
}

/** 값을 보고 정하는 페이지: 머리 줄(경로)과 SettingsBody. */
export function SettingsPage({ crumbs, ...body }: SettingsBodyProps & { crumbs: Crumb[] }) {
  return (
    <Page crumbs={crumbs}>
      <SettingsBody {...body} />
    </Page>
  )
}

import type { ReactNode } from "react"
import { Field, FieldContent, FieldDescription, FieldTitle } from "@/shared/ui/kit/field"

type SettingsRowProps = {
  /** 이름. 링크처럼 글자가 아닌 것도 된다(저장소 연동의 저장소 주소). */
  label: ReactNode
  description?: ReactNode
  /** 값이나 조작. 없으면 보조색 "-". */
  children?: ReactNode
  /** 값 없이 이름과 설명만 읽는 줄이면 false("-"도 두지 않는다). */
  hasValue?: boolean
  /**
   * 넓은 조작(고르기 묶음, 선택 상자)은 줄이 좁으면 이름 아래로 내려 전체 폭을 쓴다.
   * 스위치 같은 작은 조작은 좁아도 이름 옆에 둔다.
   */
  wide?: boolean
}

/** 설정 한 줄: 왼쪽에 이름과 설명, 오른쪽에 값이나 조작. 줄 높이 44px 이상, 안쪽 12px. */
export function SettingsRow({ label, description, children, hasValue = true, wide = false }: SettingsRowProps) {
  return (
    <Field
      orientation={wide ? "responsive" : "horizontal"}
      className="min-h-11 p-3 has-[>[data-slot=field-content]]:items-center @md/field-group:has-[>[data-slot=field-content]]:items-center"
    >
      <FieldContent>
        <FieldTitle>{label}</FieldTitle>
        {description && <FieldDescription>{description}</FieldDescription>}
      </FieldContent>
      {hasValue && (children ?? <span className="text-muted-foreground">-</span>)}
    </Field>
  )
}

import { useId, type ReactNode } from "react"
import { Card } from "@/shared/ui/kit/card"
import { FieldGroup } from "@/shared/ui/kit/field"

type SettingsSectionProps = {
  title: string
  /** 이름 줄 끝의 동작(저장, 새 토큰). */
  action?: ReactNode
  /** 카드 아래 한 줄 메모. */
  note?: ReactNode
  /** SettingsRow들. */
  children: ReactNode
}

/** 설정 한 묶음: 작은 이름, 줄을 선으로 나눈 안쪽 여백 없는 Card, 선택적인 메모. */
export function SettingsSection({ title, action, note, children }: SettingsSectionProps) {
  const titleId = useId()
  return (
    <section aria-labelledby={titleId} className="flex flex-col gap-2">
      <div className="flex min-h-7 items-center justify-between gap-2">
        <h2 id={titleId} className="text-sm font-medium text-muted-foreground">{title}</h2>
        {action}
      </div>
      <Card className="py-0">
        {/* divide-y는 줄 사이에만 선을 그어 마지막 줄 아래가 카드 테두리와 겹치지 않는다. */}
        <FieldGroup className="gap-0 divide-y divide-border">{children}</FieldGroup>
      </Card>
      {note && <p className="text-sm text-muted-foreground">{note}</p>}
    </section>
  )
}
